// Waskie, uzasadnione @SuppressWarnings:
@SuppressWarnings("unchecked") // uzasadnienie: tablica z ArrayList<T>.toArray(), wiec kazdy element to T
static <T> T pierwszyElement(List<T> lista) {
    Object[] tablica = lista.toArray();
    return (T) tablica[0];
}

// @SafeVarargs na metodzie static:
@SafeVarargs
static <T> List<T> listOf(T... elementy) {
    List<T> wynik = new ArrayList<>();
    for (T e : elementy) wynik.add(e);
    return wynik;
}

// Wildcard capture helper:
static void swap(List<?> lista, int i, int j) {
    swapHelper(lista, i, j); // deleguje do generycznej metody
}
static <T> void swapHelper(List<T> lista, int i, int j) {
    T temp = lista.get(i);
    lista.set(i, lista.get(j));
    lista.set(j, temp);
}
